pub fn wrap(text: Str, width: Int) -> List[Str] {
  let words = text.split(" ").filter(fn(x) => x != "")
  var pieces: List[Str] = []
  for w in words {
    var rest = w
    while rest.len() > width {
      pieces = pieces.push(rest.slice(0, width))
      rest = rest.slice(width, rest.len())
    }
    pieces = pieces.push(rest)
  }
  var lines: List[Str] = []
  var cur = ""
  for p in pieces {
    if cur == "" {
      cur = p
    } else if cur.len() + 1 + p.len() <= width {
      cur = cur + " " + p
    } else {
      lines = lines.push(cur)
      cur = p
    }
  }
  if cur != "" {
    lines = lines.push(cur)
  }
  return lines
}
